package org.icu.sepsis.deterioration;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.time.*;import java.util.*;import org.bson.Document;import com.mongodb.client.MongoClients;import com.mongodb.client.model.Sorts;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.beans.factory.ObjectProvider;import org.icu.sepsis.integration.*;import org.icu.sepsis.config.RuleConfig;import org.icu.sepsis.domain.ClinicalRules;import org.icu.sepsis.sepsis.SepsisAssessmentService;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
@EnabledIfEnvironmentVariable(named="LOCAL_MONGO_TESTS",matches="1") class LocalMongoDeteriorationTest{
 @Test void realLocalSourceAdapterFeedsMultiOrganWithoutSourceWrites(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var source=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));assertTrue(source.isReadable());var latest=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).first();assertNotNull(latest,"Local observation fixture is required");var patient=source.loadPatient(latest.getString("pid"));var asOf=latest.getDate("time").toInstant();ClinicalDataProvider data=(id,stay,from,to)->source.observations(id,stay,patient.department,from,to);var cfg=new RuleConfig();ObjectProvider<SmartCareSourceReader> reader=mock(ObjectProvider.class);when(reader.getIfAvailable()).thenReturn(source);var assessment=new SepsisAssessmentService(data,new ClinicalRules(cfg),cfg,reader,"smartcare",mock(ObjectProvider.class));var result=new DeteriorationService(data,assessment).read(patient,asOf);assertEquals(patient.id,result.get("patientId"));assertEquals(patient.encounterId,result.get("encounterId"));assertEquals(6,((List<?>)result.get("organs")).size());assertEquals("candidate_review_only",result.get("clinicalUse"));assertNull(result.get("complete"));System.out.println("LOCAL_READONLY_REPLAY: six organ systems; real adapter; retrospective logic only; no source writes");}}

 @Test void actualLocalOxygenWeightAndSedationPathsAreReadWithoutGuessingUnits(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var reader=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));int checked=0;for(String code:List.of("param_FiO2","param_体重","param_score_rass_obs","param_niaoLiang")){var raw=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("code",code).append("valid",true).append("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).maxTime(5,java.util.concurrent.TimeUnit.SECONDS).first();assertNotNull(raw,"Local extra-field fixture required");var patient=reader.loadPatient(raw.getString("pid"));var asOf=raw.getDate("time").toInstant();var rows=reader.observations(patient.id,patient.encounterId,patient.department,asOf.minus(Duration.ofHours(24)),asOf);assertTrue(rows.stream().anyMatch(o->code.equals(o.sourceParameterCode)),"Actual field path must survive the adapter");checked++;}assertEquals(4,checked);System.out.println("LOCAL_EXTRA_FIELDS: oxygen, weight, sedation paths verified; read only; no source writes");}}

 @Test void realSourceQualityReadUsesTheActualAdapterWithoutSourceWrites(){try(var client=MongoClients.create("mongodb://127.0.0.1:27017/?serverSelectionTimeoutMS=3000")){var source=new SmartCareSourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"));var latest=client.getDatabase("SmartCare").getCollection("bedside").find(new Document("time",new Document("$type","date")).append("pid",new Document("$regex","^[0-9a-fA-F]{24}$"))).sort(Sorts.descending("time")).first();assertNotNull(latest);var p=source.loadPatient(latest.getString("pid"));var asOf=latest.getDate("time").toInstant();ClinicalDataProvider data=(id,stay,from,to)->source.observations(id,stay,p.department,from,to);var q=new DataQualityService(data,new RuleConfig()).read(p,asOf);assertEquals(p.id,q.get("patientId"));assertEquals(p.encounterId,q.get("encounterId"));assertEquals(true,q.get("available"));assertFalse(((List<?>)q.get("items")).isEmpty());var drugs=new Icu05SourceReader(new MongoTemplate(client,"SmartCare"),new MongoTemplate(client,"DataCenter"),source,"血培养","reviewTime");ObjectProvider<Icu05SourceReader> provider=mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(drugs);var renal=mock(DeteriorationService.class);when(renal.read(any(),any())).thenReturn(Map.of());var medications=new RenalMedicationReviewService(provider,renal).read(p,asOf);assertEquals(p.id,medications.get("patientId"));assertNotEquals("failed",medications.get("sourceStatus"));System.out.println("LOCAL_SOURCE_FEATURES: scoped quality and medication adapters read verified; source read only; renal context separately tested");}}
}
